/**
 * Precision corpus tests (Phase 4)
 * Run with: node --import ./tools/json-loader.mjs --test src/lib/__tests__/corpus-precision.node-test.mjs
 *
 * Verifies false positive rates on the clean (Opus-rewritten) corpus.
 * Every finding on a non-note block is a false positive.
 *
 * Requires: corpus/results/clean-results.json (generated by run-corpus-test.mjs --corpus clean)
 */
import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, existsSync } from 'node:fs';

const resultsPath = new URL('../../../corpus/results/clean-results.json', import.meta.url);
const dataExists = existsSync(resultsPath);

describe('Precision: false positive rates on clean corpus', {
  skip: !dataExists && 'Clean results not generated yet — run: node --import ./tools/json-loader.mjs tools/run-corpus-test.mjs --corpus clean'
}, () => {
  let results;
  if (dataExists) {
    results = JSON.parse(readFileSync(resultsPath, 'utf-8'));
  }

  it('static rules: FP rate does not regress beyond baseline (0.31% = 8 FPs on 2583 blocks)', () => {
    const staticFP = results.findings.filter(f => f.engine === 'static' && !f.isNoteBlock);
    const blocksProcessed = results.stats?.blocksProcessed || 1;
    const rate = staticFP.length / blocksProcessed;
    console.log(`    Static FPs: ${staticFP.length} on ${blocksProcessed} blocks (${(rate * 100).toFixed(2)}%)`);
    if (staticFP.length > 0) {
      const byRule = {};
      for (const f of staticFP) { byRule[f.ruleId] = (byRule[f.ruleId] || 0) + 1; }
      console.log(`    By rule: ${JSON.stringify(byRule)}`);
    }
    // Baseline: 95 FPs (3.68%). Threshold: 5% (allows headroom, fails on regression).
    // Target: <2% after engine tuning.
    assert.ok(rate < 0.05,
      `Static FP rate ${(rate * 100).toFixed(2)}% exceeds 5% regression threshold (${staticFP.length} FPs)`);
  });

  it('NLP rules: FP rate does not regress beyond baseline (12.8% = 331 FPs on 2583 blocks)', () => {
    const nlpFP = results.findings.filter(f => f.engine === 'nlp' && !f.isNoteBlock);
    const blocksProcessed = results.stats?.blocksProcessed || 1;
    const rate = nlpFP.length / blocksProcessed;
    console.log(`    NLP FPs: ${nlpFP.length} on ${blocksProcessed} blocks (${(rate * 100).toFixed(2)}%)`);
    // Baseline: 403 FPs (15.6%). compromise.js passive voice detection has inherent FPs on
    // spec language (adjective past participles like "galvanized", "reinforced").
    // Threshold: 20% (allows headroom, fails on regression).
    // Target: <10% after pattern refinement.
    assert.ok(rate < 0.20,
      `NLP FP rate ${(rate * 100).toFixed(2)}% exceeds 20% regression threshold (${nlpFP.length} FPs)`);
  });

  it('note block exemption: zero static/NLP findings on note blocks', () => {
    const noteStatic = results.findings.filter(f => f.engine === 'static' && f.isNoteBlock);
    const noteNlp = results.findings.filter(f => f.engine === 'nlp' && f.isNoteBlock);
    console.log(`    Note block findings: ${noteStatic.length} static, ${noteNlp.length} NLP`);
    assert.equal(noteStatic.length, 0, `${noteStatic.length} static findings on note blocks`);
    assert.equal(noteNlp.length, 0, `${noteNlp.length} NLP findings on note blocks`);
  });
});
